"""Conservative closed-loop candidate policy for the Last10m controller."""


# EVOLVE-BLOCK-START
def decide(observation, memory):
    """Use safety gating, short-term target confirmation, and hysteretic steering."""
    memory = dict(memory or {})
    state = memory.get("state", "IDLE")
    last_action = memory.get("last_action", "")
    scan_direction = memory.get("scan_direction", "SCAN_LEFT")
    scan_hold = int(memory.get("scan_hold", 0))

    visible = bool(observation["target_visible"])
    bearing = float(observation["target_bearing"])
    distance = observation["target_distance_class"]
    target_conf = float(observation["target_confidence"])
    identity_conf = float(observation["target_identity_confidence"])
    track_age = int(observation["track_age"])
    lost_steps = int(observation["lost_steps"])
    safety_conf = float(observation["safety_confidence"])
    closing_risk = float(observation["closing_risk"])
    heading_error = float(observation["heading_error"])

    def emit(action, confidence, next_state):
        memory["state"] = next_state
        memory["last_action"] = action
        return action, confidence, memory

    if safety_conf < 0.60 or closing_risk >= 0.75:
        return emit("STOP", 0.99, "STOPPED")

    confirmed = (
        visible and target_conf >= 0.55 and identity_conf >= 0.60
    )
    if not confirmed:
        memory["state"] = "REACQUIRE" if (
            state in {"LOCKED", "APPROACH", "VERIFY", "REACQUIRE"} or lost_steps
        ) else "SEARCH"

        if lost_steps <= 1:
            return emit("STOP", 0.92, memory["state"])

        if scan_hold > 0:
            memory["scan_hold"] = scan_hold - 1
            return emit(scan_direction, 0.74, "REACQUIRE")

        scan_direction = (
            "SCAN_RIGHT" if scan_direction == "SCAN_LEFT" else "SCAN_LEFT"
        )
        memory["scan_direction"] = scan_direction
        memory["scan_hold"] = 1
        return emit(scan_direction, 0.76, "REACQUIRE")

    if track_age < 2:
        return emit("SLOW_DOWN", 0.80, "VERIFY")

    if distance == "near":
        if abs(heading_error) <= 15.0 and identity_conf >= 0.80:
            return emit("ARRIVED", 0.96, "ARRIVED")
        turn = bearing if abs(bearing) > 2.0 else heading_error
        return emit(
            "VEER_LEFT" if turn < 0.0 else "VEER_RIGHT",
            0.87,
            "APPROACH",
        )

    # Keep an established turn through small bearing noise, but reverse
    # immediately when the target is decisively on the opposite side.
    if bearing < -12.0 and observation["corridor_left"]:
        action = "VEER_LEFT"
    elif bearing > 12.0 and observation["corridor_right"]:
        action = "VEER_RIGHT"
    elif -8.0 <= bearing <= 8.0 and last_action in {
        "VEER_LEFT", "VEER_RIGHT"
    }:
        action = last_action
    elif observation["corridor_center"]:
        action = "FORWARD"
    elif bearing < 0.0 and observation["corridor_left"]:
        action = "VEER_LEFT"
    elif bearing > 0.0 and observation["corridor_right"]:
        action = "VEER_RIGHT"
    elif observation["corridor_left"]:
        action = "VEER_LEFT"
    elif observation["corridor_right"]:
        action = "VEER_RIGHT"
    else:
        return emit("STOP", 0.98, "STOPPED")

    return emit(action, 0.90 if action == "FORWARD" else 0.84, "APPROACH")


# EVOLVE-BLOCK-END
